from pathlib import Path
R=Path(__file__).resolve().parents[3]
def replace(path,old,new):
 p=R/path;s=p.read_text(encoding='utf-8');assert old in s,(path,old);p.write_text(s.replace(old,new),encoding='utf-8')
replace(Path('README.md'),'Phase two remains deferred.','The [phase-two spatial update](docs/patches/combat-phase-two/README.md) aligns native melee reach with Better Combat size scaling, prevents hostile skill locks during Vanish, adds gentle Flame Slash homing and contains Purgatory enemies in a visible orange boundary. Barrage retains its existing ordinary-arrow assist.')
replace(Path('docs/MODLIST.md'),'Purgatory has a 12s base cooldown.','Purgatory has a 12s base cooldown. Its first pulse pulls enemies strongly inward; an orange wall contains enemies at the 12-block outer radius, or 14 with Improved, until channeling ends. The wall is five blocks high, open above, and lets allies and projectiles pass. Vanish prevents hostile skill selection and maintained homing locks, while untargeted damage still works. Flame Slash gently seeks visible nearby enemies. Native melee reach now follows the same size scaling as Better Combat.')
replace(Path('mod fixing/README.md'),'Phase two remains pending; no personal/live server or GitHub push.','Phase two is covered by [the spatial patch](../docs/patches/combat-phase-two/README.md); no personal/live server or GitHub push.')
for file,text in [
 ('Paladin skills - raw attributes and nodes.md','Purgatory now has a strong first-pulse pull and a visible orange, five-block-high enclosure at the 12/14-block outer pull radius. It contains hostile living entities, while the caster, party allies and pets pass. No roof, projectile interception, teleport prevention or placed blocks. Release, completion, interruption, death, logout, dimension change, respec and teleport cleanup remove it. Inner damage radius and later stage balance remain unchanged.'),
 ('Rogue skills - raw attributes and nodes.md','Vanish prevents hostile targeted skills from acquiring or retaining you. A synchronized Vanish flag removes remote client highlights, and the server rejects stale selections. Ordinary invisibility and friendly targets remain eligible; untargeted areas and physical impacts still deal damage. Archer ordinary assist, Magic Arrows and native homing drop vanished enemies. Existing breathing visuals and mark cleanup remain.'),
 ('Magic spells - raw attributes and nodes.md','Flame Slash retains free-aim casting, 16-block travel, speed 0.9, piercing and 80% Fire damage. It now seeks the nearest visible eligible enemy within 8 blocks, steering up to 2 degrees per tick and refreshing acquisition every 4 ticks. Party allies and vanished enemies are excluded.'),
 ('Warrior skills - raw attributes and nodes.md','Native entity interaction reach now follows Better Combat\'s existing proportional size multiplier. Growth increases usable melee reach and shrinking reduces it without a persistent reach modifier; removal immediately restores the prior range. Block reach is unchanged. The original affected player\'s exact saved build was unavailable; the native/client range mismatch was reproduced with controlled scale fixtures.')]:
 p=R/'mod fixing'/file;s=p.read_text(encoding='utf-8');s+='\n\n## Combat phase two - 2 November 2026\n\n'+text+'\n';p.write_text(s,encoding='utf-8')
